head.script:
/**
 * [래퍼 페이지] MFEClient E-NO-SERVER 기능 데모
 * - txa_log: 로그 출력용 textarea
 * - wf_main: 하위 페이지(demo.xml) 로드
 */
scwin.log = function(msg) {
    var txa = $p.getComponentById("txa_log");
    var timestamp = new Date().toLocaleTimeString();
    txa.setValue(txa.getValue() + "[" + timestamp + "] " + msg + "\n");
    // 스크롤을 맨 아래로
    var el = txa.render;
    if (el) el.scrollTop = el.scrollHeight;
};

scwin.btn_clear_onclick = function() {
    $p.getComponentById("txa_log").setValue("");
};

body.script:
scwin.onpageload = function() {
    scwin.log("=== 래퍼 페이지 로드 완료 ===");
};
